(807304, 90152, 20662, '<td valign="top">Wouldn''t freedom be without that binding bra?</td>', 'Wouldn''t freedom be without that binding bra?', '2004-07-12 13:36:59.000000', NULL, 1),
(807306, 90575, 7322, '<td valign="top">The vertical framing, the diagonals created by texture of the sand, and the generous cropping at the bottom combine to create a very dynamic composition. The shadow adds greater energy. Very good.</td>', 'The vertical framing, the diagonals created by texture of the sand, and the generous cropping at the bottom combine to create a very dynamic composition. The shadow adds greater energy. Very good.', '2004-07-12 13:37:49.000000', NULL, 1),
(807307, 90111, 7322, '<td valign="top">I don''t like the use of selective desaturation. This doesn''t really say anything about freedom to me. It has a too perfect, plastic quality. I like the composition.</td>', 'I don''t like the use of selective desaturation. This doesn''t really say anything about freedom to me. It has a too perfect, plastic quality. I like the composition.', '2004-07-12 13:38:55.000000', NULL, 1),
(807311, 90483, 20662, '<td valign="top">like the idea -- maybe a brighter color balloon against the sky would have been more eye catching</td>', 'like the idea -- maybe a brighter color balloon against the sky would have been more eye catching', '2004-07-12 13:40:05.000000', NULL, 1),
(807315, 90335, 20662, '<td valign="top">I might have cropped this a little closer but then it may have taken away from the feeling of floating. Hmmm...</td>', 'I might have cropped this a little closer but then it may have taken away from the feeling of floating. Hmmm...', '2004-07-12 13:41:25.000000', NULL, 1),
(807317, 90287, 7322, '<td valign="top">This apears a bit too contrasty. His distorted shadow doesn''t really add much to the composition which suggests a different POV would have worked better. Despite the bright color and flowy costume, I''m finding this a rather dull composition.</td>', 'This apears a bit too contrasty. His distorted shadow doesn''t really add much to the composition which suggests a different POV would have worked better. Despite the bright color and flowy costume, I''m finding this a rather dull composition.', '2004-07-12 13:41:31.000000', NULL, 1),
(807319, 89226, 20662, '<td valign="top">Irony? Maybe you could have helped one escape!</td>', 'Irony? Maybe you could have helped one escape!', '2004-07-12 13:42:35.000000', NULL, 1),
(807324, 90558, 20662, '<td valign="top">San Diego? <br/> <br/>Very nicely done.</td>', 'San Diego?  Very nicely done.', '2004-07-12 13:45:38.000000', NULL, 1),
(807325, 90580, 13136, '<td valign="top">Wow. What a concept.</td>', 'Wow. What a concept.', '2004-07-12 13:45:53.000000', NULL, 1),
(807327, 90568, 7322, '<td valign="top">This is the kind of set-up shot that should be done over and over until the perfect capture is achieved. This is just kind of boring despite the action. The cropping at the bottom is too tight to get the sense of height and movement this shot needs. The girl on the left has the better expression but she has barely left the platform. The girl on the right has gotten some air beneath her but her expression is to placid. Without a frame of reference, it is hard to get excited about this jump. For all the viewer knows, they are only a foot off the ground. This possibility takes a lot of the exhilaration away for me. <br/> <br/>The focus is a bit soft for an action shot. <br/> <br/>The typo in the title should have been fixed before the deadline. That kind of error just looks sloppy to me.</td>', 'This is the kind of set-up shot that should be done over and over until the perfect capture is achieved. This is just kind of boring despite the action. The cropping at the bottom is too tight to get the sense of height and movement this shot needs. The girl on the left has the better expression but she has barely left the platform. The girl on the right has gotten some air beneath her but her expression is to placid. Without a frame of reference, it is hard to get excited about this jump. For all the viewer knows, they are only a foot off the ground. This possibility takes a lot of the exhilaration away for me.  The focus is a bit soft for an action shot.  The typo in the title should have been fixed before the deadline. That kind of error just looks sloppy to me.', '2004-07-12 13:47:33.000000', NULL, 1),
(807331, 90480, 7322, '<td valign="top">Cute. It seems a bit of a stretch since that snail likely isn''t going anywhere but back into captivity when this shoot is done but it is a well executed set-up. My guess is you''ll do well with it.</td>', 'Cute. It seems a bit of a stretch since that snail likely isn''t going anywhere but back into captivity when this shoot is done but it is a well executed set-up. My guess is you''ll do well with it.', '2004-07-12 13:49:14.000000', NULL, 1),
(807333, 90574, 7322, '<td valign="top">It''s a bit dark in the foreground to really get a sense of this scene. The expanse of sky, the clouds, and the mountains are not dramatic enough to carry the weight of the composition.</td>', 'It''s a bit dark in the foreground to really get a sense of this scene. The expanse of sky, the clouds, and the mountains are not dramatic enough to carry the weight of the composition.', '2004-07-12 13:50:56.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(807335, 90356, 24079, '<td valign="top">very cute!</td>', 'very cute!', '2004-07-12 13:52:14.000000', NULL, 1),
(807336, 89994, 7322, '<td valign="top">Context? I have no idea what this represents so I can''t really evaluate it in terms of the challenge. Photographically: the subject doesn''t engage me and on purely graphic terms, there just isn''t enough dynamics to grab me either.</td>', 'Context? I have no idea what this represents so I can''t really evaluate it in terms of the challenge. Photographically: the subject doesn''t engage me and on purely graphic terms, there just isn''t enough dynamics to grab me either.', '2004-07-12 13:52:48.000000', NULL, 1),
(807337, 90361, 24079, '<td valign="top">beautiful detail and colors</td>', 'beautiful detail and colors', '2004-07-12 13:53:08.000000', NULL, 1),
(807341, 90381, 7322, '<td valign="top">This has a very tenuous connection to the challenge for me. It''s a cute shot of the squirrel but there really isn''t anything about the manner in which he is clinging to the tree that suggest freedom to me. The acorn thing is just stretching it, IMO. After all, unlike the photographer on the ground, the squirrel has easy access to the acorns, so the title doesn''t even make sense.</td>', 'This has a very tenuous connection to the challenge for me. It''s a cute shot of the squirrel but there really isn''t anything about the manner in which he is clinging to the tree that suggest freedom to me. The acorn thing is just stretching it, IMO. After all, unlike the photographer on the ground, the squirrel has easy access to the acorns, so the title doesn''t even make sense.', '2004-07-12 13:55:57.000000', NULL, 1),
(807351, 90107, 7322, '<td valign="top">This guy just doesn''t look abnormal. He is decently dressed for one thing; his  t-shirt is even tucked in with a belt. The arm gesture and open doesn''t carry enough weight without further context.</td>', 'This guy just doesn''t look abnormal. He is decently dressed for one thing; his  t-shirt is even tucked in with a belt. The arm gesture and open doesn''t carry enough weight without further context.', '2004-07-12 13:59:05.000000', NULL, 1),
(807359, 90572, 7322, '<td valign="top">It does represent a kind of freedom but in a rather dull way. It''s nice scenery but nothing overly inspiring. The camper, chairs, and picnic table just aren''t compelling enough subject matter. Perhaps a human element would have added some interest for me.</td>', 'It does represent a kind of freedom but in a rather dull way. It''s nice scenery but nothing overly inspiring. The camper, chairs, and picnic table just aren''t compelling enough subject matter. Perhaps a human element would have added some interest for me.', '2004-07-12 14:01:32.000000', NULL, 1),
(807365, 90507, 7322, '<td valign="top">Without context (I don''t know where this is or what is being represented besides war and Christianity) it doesn''t say much about freedom to me. I''ll assume it is a historical battle site from the American Revolution. <br/>Photographically, it is a rather dull and literal interpretation. It is very static and lacking in drama or mood of any kind.</td>', 'Without context (I don''t know where this is or what is being represented besides war and Christianity) it doesn''t say much about freedom to me. I''ll assume it is a historical battle site from the American Revolution. Photographically, it is a rather dull and literal interpretation. It is very static and lacking in drama or mood of any kind.', '2004-07-12 14:06:18.000000', NULL, 1),
(807368, 90022, 7322, '<td valign="top">The main subject, the plane, is too tiny in the frame to make an impact. It just looks like the camera was pointed at the sky as it passed over.</td>', 'The main subject, the plane, is too tiny in the frame to make an impact. It just looks like the camera was pointed at the sky as it passed over.', '2004-07-12 14:08:05.000000', NULL, 1),
(807372, 90348, 7322, '<td valign="top">I know one should move in close to the subject but this is a bit too close. The human skull has many interesting contours and planes but we aren''t seeing much of that due to the claustrophobic cropping.</td>', 'I know one should move in close to the subject but this is a bit too close. The human skull has many interesting contours and planes but we aren''t seeing much of that due to the claustrophobic cropping.', '2004-07-12 14:10:23.000000', NULL, 1),
(807381, 90418, 7322, '<td valign="top">This looks rather like one of those paparazzi snap shots one finds in party scenes in People magazine. The cropping of his right foot appears haphazzard. His jacket completes disappears into the dark background (flash is too close and bright--suggest slow-synch flash next time). It looks a bit like he has badly touched-up red-eye which makes me think the smallness of the image is hiding things.</td>', 'This looks rather like one of those paparazzi snap shots one finds in party scenes in People magazine. The cropping of his right foot appears haphazzard. His jacket completes disappears into the dark background (flash is too close and bright--suggest slow-synch flash next time). It looks a bit like he has badly touched-up red-eye which makes me think the smallness of the image is hiding things.', '2004-07-12 14:13:30.000000', NULL, 1),
(807386, 90417, 7322, '<td valign="top">The cropping is just a tad too generous. While there needs to be some suggestion of wide open water, the main subject is too small to have much of an impact.</td>', 'The cropping is just a tad too generous. While there needs to be some suggestion of wide open water, the main subject is too small to have much of an impact.', '2004-07-12 14:18:29.000000', NULL, 1),
(807388, 90248, 7322, '<td valign="top">Pretty standard clouds shot. There really isn''t anything to grab on to after an initial glance.</td>', 'Pretty standard clouds shot. There really isn''t anything to grab on to after an initial glance.', '2004-07-12 14:19:17.000000', NULL, 1),
(807394, 90518, 7322, '<td valign="top">I''ve exercise my freedom to determine that this has a really tenous connection to the challenge. <br/> <br/>Photographically, it''s rather contrasty. Most of the flowers have gone to seed so there isn''t really a lot of color happening except the orange and green. Because of the high contrast there isn''t a lot of detail to be seen in terms of texture. It''s just kind of boring.</td>', 'I''ve exercise my freedom to determine that this has a really tenous connection to the challenge.  Photographically, it''s rather contrasty. Most of the flowers have gone to seed so there isn''t really a lot of color happening except the orange and green. Because of the high contrast there isn''t a lot of detail to be seen in terms of texture. It''s just kind of boring.', '2004-07-12 14:22:43.000000', NULL, 1),
(807395, 90113, 7322, '<td valign="top">This is appears extremely contrasty to me. The main subject is a bit small in the frame to really grab my interest. It is a nice capture of the dramatic clouds.</td>', 'This is appears extremely contrasty to me. The main subject is a bit small in the frame to really grab my interest. It is a nice capture of the dramatic clouds.', '2004-07-12 14:23:32.000000', NULL, 1),
(807398, 90454, 7322, '<td valign="top">I don''t understand the title because of the weird comma placement. I don''t know if that is a typo or just a quirky choice of phrasing. I don''t understand the context which makes it very hard for me to evaluate this in terms of the challenge. <br/> <br/>Photographically, the blue portion is just to dark for me to make much of it. It blends almost seemlessly into the background on my Apple monitor.</td>', 'I don''t understand the title because of the weird comma placement. I don''t know if that is a typo or just a quirky choice of phrasing. I don''t understand the context which makes it very hard for me to evaluate this in terms of the challenge.  Photographically, the blue portion is just to dark for me to make much of it. It blends almost seemlessly into the background on my Apple monitor.', '2004-07-12 14:26:01.000000', NULL, 1),
(807403, 90144, 7322, '<td valign="top">I like the photo quite a bit but I agree it has a tenuous connection to the challenge. For one thing, I dislike defining a term by its opposite which is essentially what has been done  here. <br/> <br/>Photographically, I like the mood, the verticals created by the drapes, the triangle of light peeping out, and the clearly defined sillouhette of teh cat. Pretty much everything, in fact.</td>', 'I like the photo quite a bit but I agree it has a tenuous connection to the challenge. For one thing, I dislike defining a term by its opposite which is essentially what has been done  here.  Photographically, I like the mood, the verticals created by the drapes, the triangle of light peeping out, and the clearly defined sillouhette of teh cat. Pretty much everything, in fact.', '2004-07-12 14:31:39.000000', NULL, 1),
(807407, 90577, 7322, '<td valign="top">A feather duster escaped? <br/> <br/>Interesting composition. I''m not reading the feathers as an escaped bird but I get the idea.</td>', 'A feather duster escaped?  Interesting composition. I''m not reading the feathers as an escaped bird but I get the idea.', '2004-07-12 14:33:33.000000', NULL, 1),
(807415, 90452, 6097, '<td valign="top">I love the look of this photo.  Love the pastel colors here.  The exposure is excellent IMO  Does give a free and fresh feeling.  Great shot!!!  Good luck with the challenge!!!</td>', 'I love the look of this photo.  Love the pastel colors here.  The exposure is excellent IMO  Does give a free and fresh feeling.  Great shot!!!  Good luck with the challenge!!!', '2004-07-12 14:38:14.000000', NULL, 1),
(807418, 90283, 7322, '<td valign="top">No. Flowers grow according to laws of nature. They do not grow with any kind of inner motivation or desires.</td>', 'No. Flowers grow according to laws of nature. They do not grow with any kind of inner motivation or desires.', '2004-07-12 14:40:43.000000', NULL, 1),
(807421, 90353, 7322, '<td valign="top">A bit oversaturated but the composition has a certain energy.</td>', 'A bit oversaturated but the composition has a certain energy.', '2004-07-12 14:41:24.000000', NULL, 1),
(807423, 90416, 7322, '<td valign="top">The plane is too small in the picture frame to make an impact.</td>', 'The plane is too small in the picture frame to make an impact.', '2004-07-12 14:42:10.000000', NULL, 1),
(807427, 89917, 7322, '<td valign="top">There is just not enough context to make a connection to the challenge. It is a youngish, white man with his head in his hands,  possibly blockin his ears. He appears to be upset or in deep thought. His clothes and his enviroment don''t offer enough clues. I''ve thought about it and I still haven''t figured it out. Sorry.</td>', 'There is just not enough context to make a connection to the challenge. It is a youngish, white man with his head in his hands,  possibly blockin his ears. He appears to be upset or in deep thought. His clothes and his enviroment don''t offer enough clues. I''ve thought about it and I still haven''t figured it out. Sorry.', '2004-07-12 14:45:44.000000', NULL, 1),
(807435, 90384, 7322, '<td valign="top">Free enterprise? Cute idea. The photo has too much of a family snap shot quality for me to enjoy it.</td>', 'Free enterprise? Cute idea. The photo has too much of a family snap shot quality for me to enjoy it.', '2004-07-12 14:52:42.000000', NULL, 1),
(807437, 90483, 7322, '<td valign="top">Perhaps a different color balloon to contrast with the blue sky would have made this more interesting. The focus is a bit too soft.</td>', 'Perhaps a different color balloon to contrast with the blue sky would have made this more interesting. The focus is a bit too soft.', '2004-07-12 14:53:23.000000', NULL, 1),
