(809043, 90376, 12733, '<td valign="top">Freedom or insanity? I think this is over the top for the challenge.</td>', 'Freedom or insanity? I think this is over the top for the challenge.', '2004-07-13 13:27:42.000000', NULL, 1),
(809044, 90410, 12733, '<td valign="top">Nice illustration of freedom of speech. Possibly could have been cropped a bit tighter to remove the unreadable sign at the top. This sign might make sense in a larger print - assuming it fits the theme. I like the pigeon that seems to be reading the signs.</td>', 'Nice illustration of freedom of speech. Possibly could have been cropped a bit tighter to remove the unreadable sign at the top. This sign might make sense in a larger print - assuming it fits the theme. I like the pigeon that seems to be reading the signs.', '2004-07-13 13:29:48.000000', NULL, 1),
(809046, 90352, 12733, '<td valign="top">Nice concept, sharp photo.</td>', 'Nice concept, sharp photo.', '2004-07-13 13:30:42.000000', NULL, 1),
(809048, 89870, 12733, '<td valign="top">Nice use of background blur to show motion. The runner''s blurry foot and hand are distracting, though.</td>', 'Nice use of background blur to show motion. The runner''s blurry foot and hand are distracting, though.', '2004-07-13 13:31:47.000000', NULL, 1),
(809050, 90562, 12733, '<td valign="top">Interesting symbolism, and clever processing. I''d love to know how you did it - are you planning to submit a tutorial?</td>', 'Interesting symbolism, and clever processing. I''d love to know how you did it - are you planning to submit a tutorial?', '2004-07-13 13:32:46.000000', NULL, 1),
(809051, 90548, 12733, '<td valign="top">I agree with the sentiment. Was F 9-11 the only name in red, or was this post-processing?</td>', 'I agree with the sentiment. Was F 9-11 the only name in red, or was this post-processing?', '2004-07-13 13:35:21.000000', NULL, 1),
(809052, 90578, 12733, '<td valign="top">Nice action, great expression, sharp photo.</td>', 'Nice action, great expression, sharp photo.', '2004-07-13 13:35:44.000000', NULL, 1),
(809054, 89487, 12733, '<td valign="top">Less is more - you''ve included enough of the bike to make the point, but not so much that the machine becomes the subject rather than the rider.</td>', 'Less is more - you''ve included enough of the bike to make the point, but not so much that the machine becomes the subject rather than the rider.', '2004-07-13 13:36:37.000000', NULL, 1),
(809056, 90341, 12733, '<td valign="top">...and it sure seems to have a lot to say. I could think of some great captions for this shot - very nice.</td>', '...and it sure seems to have a lot to say. I could think of some great captions for this shot - very nice.', '2004-07-13 13:37:30.000000', NULL, 1),
(809057, 90124, 12733, '<td valign="top">Great shot - perfect timing, and it really gets the message across. Pictures like this don''t always come without a cost either.</td>', 'Great shot - perfect timing, and it really gets the message across. Pictures like this don''t always come without a cost either.', '2004-07-13 13:38:33.000000', NULL, 1),
(809059, 90511, 12733, '<td valign="top">Great expression. The book seems overexposed; I don''t know what cutting back would do to the reader, though.</td>', 'Great expression. The book seems overexposed; I don''t know what cutting back would do to the reader, though.', '2004-07-13 13:40:20.000000', NULL, 1),
(809060, 90454, 12733, '<td valign="top">The coloring looks totally unnatural and kind of disturbing.</td>', 'The coloring looks totally unnatural and kind of disturbing.', '2004-07-13 13:41:06.000000', NULL, 1),
(809061, 89226, 12733, '<td valign="top">Free as what bird? These don''t look in the least bit free, and the one in the foregournd looks distinctly unhappy about it.</td>', 'Free as what bird? These don''t look in the least bit free, and the one in the foregournd looks distinctly unhappy about it.', '2004-07-13 13:42:03.000000', NULL, 1),
(809063, 90581, 12733, '<td valign="top">Interesting shot; the extreme closeup brings out detail you don''t otherwise notice.</td>', 'Interesting shot; the extreme closeup brings out detail you don''t otherwise notice.', '2004-07-13 13:42:40.000000', NULL, 1),
(809066, 90353, 12733, '<td valign="top">A nicely balanced composition. It would be absolutely perfect if the kite were just a bit redder. The diagnal string gives a nice sense of action.</td>', 'A nicely balanced composition. It would be absolutely perfect if the kite were just a bit redder. The diagnal string gives a nice sense of action.', '2004-07-13 13:44:15.000000', NULL, 1),
(809067, 90461, 12733, '<td valign="top">This is a beautiful landscape shot, but it is kind of a stretch to get to the Freedom theme.</td>', 'This is a beautiful landscape shot, but it is kind of a stretch to get to the Freedom theme.', '2004-07-13 13:44:46.000000', NULL, 1),
(809070, 90036, 12733, '<td valign="top">Great capture of a fierce bird in motion.</td>', 'Great capture of a fierce bird in motion.', '2004-07-13 13:45:32.000000', NULL, 1),
(809072, 90105, 12733, '<td valign="top">Beautiful - DOF, colors, blurred background - everything works.</td>', 'Beautiful - DOF, colors, blurred background - everything works.', '2004-07-13 13:47:00.000000', NULL, 1),
(809073, 90098, 12733, '<td valign="top">Nicely conceived and sharp, but the angle doesn''t make for the most interesting composition.</td>', 'Nicely conceived and sharp, but the angle doesn''t make for the most interesting composition.', '2004-07-13 13:48:29.000000', NULL, 1),
