(809263, 90405, 19608, '<td valign="top">Do you like watermelon?  Nice entry for freedom.</td>', 'Do you like watermelon?  Nice entry for freedom.', '2004-07-13 16:21:46.000000', NULL, 1),
(809267, 90569, 19608, '<td valign="top">Un-wanted freedom it appears.  Everything is great except the blurred glass? on the right edge.  The focus on the rings and letter is perfect -  the blurred model works really well.  It would probably be a better choice just to use the engagement ring and not the wedding band too.  Stilll an excellent entry overall.</td>', 'Un-wanted freedom it appears.  Everything is great except the blurred glass? on the right edge.  The focus on the rings and letter is perfect -  the blurred model works really well.  It would probably be a better choice just to use the engagement ring and not the wedding band too.  Stilll an excellent entry overall.', '2004-07-13 16:25:20.000000', NULL, 1),
(809268, 90219, 19608, '<td valign="top">Nice freedom in a serene setting.  Horizon does seem to be tilted which is a bit bothersome.</td>', 'Nice freedom in a serene setting.  Horizon does seem to be tilted which is a bit bothersome.', '2004-07-13 16:26:44.000000', NULL, 1),
(809276, 89878, 19608, '<td valign="top">Artistic and original.  The left hand needs to be a bit sharper and/or a different color to be effective.  The way it is - it really blends into the background so that the finger looks disconnected.  High key effect is great for this.</td>', 'Artistic and original.  The left hand needs to be a bit sharper and/or a different color to be effective.  The way it is - it really blends into the background so that the finger looks disconnected.  High key effect is great for this.', '2004-07-13 16:29:53.000000', NULL, 1),
(809280, 89904, 19608, '<td valign="top">Interesting idea and lighting.  Exposure seems to be right on.  The border needs to be set free.</td>', 'Interesting idea and lighting.  Exposure seems to be right on.  The border needs to be set free.', '2004-07-13 16:31:48.000000', NULL, 1),
(809283, 90356, 19608, '<td valign="top">An extra point for originality and humor!  Nicely setup and exposed.</td>', 'An extra point for originality and humor!  Nicely setup and exposed.', '2004-07-13 16:32:56.000000', NULL, 1),
