(809364, 90355, 3087, '<td valign="top">Though the image itself is a little boring the subject matter strikes a definite chord for me in terms of challenge theme as to me, reading opens up a whole world and I adored visiting the library as a child. 7</td>', 'Though the image itself is a little boring the subject matter strikes a definite chord for me in terms of challenge theme as to me, reading opens up a whole world and I adored visiting the library as a child. 7', '2004-07-13 17:06:27.000000', NULL, 1),
