(809375, 89917, 20779, '<td valign="top">Very moving picture and perfect balance of soft colors. The connection to the challenge may be seen as a bit of a stretch for most voters I think.</td>', 'Very moving picture and perfect balance of soft colors. The connection to the challenge may be seen as a bit of a stretch for most voters I think.', '2004-07-13 17:09:07.000000', NULL, 1),
(809378, 90353, 20779, '<td valign="top">The vantage point used really gives the feeling of freedom to it.</td>', 'The vantage point used really gives the feeling of freedom to it.', '2004-07-13 17:09:41.000000', NULL, 1),
(809382, 90480, 3087, '<td valign="top">Absolutely lovely image with a really golden quality to the snail but doesn''t really convey the theme very strongly to me. 7 in this challenge, probably 8 or 9 in a free study or different challenge.</td>', 'Absolutely lovely image with a really golden quality to the snail but doesn''t really convey the theme very strongly to me. 7 in this challenge, probably 8 or 9 in a free study or different challenge.', '2004-07-13 17:10:43.000000', NULL, 1),
