(809561, 90361, 14614, '<td valign="top">nice twist on the theme, color in the walls adds interest, lighting just great.</td>', 'nice twist on the theme, color in the walls adds interest, lighting just great.', '2004-07-13 18:40:03.000000', NULL, 1),
(809563, 90562, 22125, '<td valign="top">this is great pic, but a little scary</td>', 'this is great pic, but a little scary', '2004-07-13 18:41:48.000000', NULL, 1),
(809564, 90353, 23430, '<td valign="top">Very nice colours and framing. I''ve thought I''ve taking a shot like this I didn''t think it could turn out this good. I''d be interested to know what size lens you used.</td>', 'Very nice colours and framing. I''ve thought I''ve taking a shot like this I didn''t think it could turn out this good. I''d be interested to know what size lens you used.', '2004-07-13 18:41:52.000000', NULL, 1),
(809565, 90540, 14614, '<td valign="top">couldn''t afford a better pen :)))<br/> <br/>Creative take on the theme, glasses and pen work well (seriously - you need a better pen or one without color/writing)  border woks really well to set the monochromatic, "legal" mood.  lighting and composition very good.</td>', 'couldn''t afford a better pen :))) Creative take on the theme, glasses and pen work well (seriously - you need a better pen or one without color/writing)  border woks really well to set the monochromatic, "legal" mood.  lighting and composition very good.', '2004-07-13 18:42:12.000000', NULL, 1),
(809577, 90335, 23430, '<td valign="top">Nice colours and framing. The concept and title are also very good.</td>', 'Nice colours and framing. The concept and title are also very good.', '2004-07-13 18:46:43.000000', NULL, 1),
(809581, 90356, 22125, '<td valign="top">So cleaver.</td>', 'So cleaver.', '2004-07-13 18:48:22.000000', NULL, 1),
(809587, 90526, 3087, '<td valign="top">Love the focus on such a small detail. Composition is just prefect. Great choice to have model wear black Tshirt so that shadows and Tshirt merge. Texture and colour are excellent. Given how often I have to slip open the top button when eating too much in one or another restaurant I can really identify with the feeling of freedom this image conveys! 8</td>', 'Love the focus on such a small detail. Composition is just prefect. Great choice to have model wear black Tshirt so that shadows and Tshirt merge. Texture and colour are excellent. Given how often I have to slip open the top button when eating too much in one or another restaurant I can really identify with the feeling of freedom this image conveys! 8', '2004-07-13 19:00:17.000000', NULL, 1),
(809589, 90360, 3087, '<td valign="top">Very tranquil, nice all-blue colour palette. 7</td>', 'Very tranquil, nice all-blue colour palette. 7', '2004-07-13 19:01:17.000000', NULL, 1),
(809591, 90486, 3087, '<td valign="top">Lovely use of colour - the flowers and sunny sky plus the pose successfully convey a sense of joy. 7</td>', 'Lovely use of colour - the flowers and sunny sky plus the pose successfully convey a sense of joy. 7', '2004-07-13 19:01:57.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(809594, 90205, 3087, '<td valign="top">Very masculine legs, not that that''s a negative... Quite a quirky and riske interpretation of freedom but I like it. It''s simple, limited colours, high impact! 7</td>', 'Very masculine legs, not that that''s a negative... Quite a quirky and riske interpretation of freedom but I like it. It''s simple, limited colours, high impact! 7', '2004-07-13 19:02:55.000000', NULL, 1),
(809595, 90583, 3087, '<td valign="top">Yay! Love cows! Don''t know why this seems so surreal to me but it does. Definite feeling of cows on a journey! 7</td>', 'Yay! Love cows! Don''t know why this seems so surreal to me but it does. Definite feeling of cows on a journey! 7', '2004-07-13 19:03:40.000000', NULL, 1),
(809596, 90565, 3087, '<td valign="top">I like the bleak feel of this but think one boat rather than 4 would convey a sense of freedom more strongly. 7</td>', 'I like the bleak feel of this but think one boat rather than 4 would convey a sense of freedom more strongly. 7', '2004-07-13 19:04:40.000000', NULL, 1),
(809599, 90387, 3087, '<td valign="top">Such a strong sense of scale and such very rich colours. Excellent and unusual composition with only a sliver of land in the foreground and the heaviness of the slopes behind. Great focal point in the boat and boatmen too. 8</td>', 'Such a strong sense of scale and such very rich colours. Excellent and unusual composition with only a sliver of land in the foreground and the heaviness of the slopes behind. Great focal point in the boat and boatmen too. 8', '2004-07-13 19:05:48.000000', NULL, 1),
(809604, 90207, 3087, '<td valign="top">To me this speaks more of cheating than of freedom. It''s sad that marriage feels like such a prison to some that pretending they are single in order to live the single life is considered to be "freedom". Anyway, nicely conveyed storyline and I like that you''ve cropped out her face to retain the feeling of anonymity. 7</td>', 'To me this speaks more of cheating than of freedom. It''s sad that marriage feels like such a prison to some that pretending they are single in order to live the single life is considered to be "freedom". Anyway, nicely conveyed storyline and I like that you''ve cropped out her face to retain the feeling of anonymity. 7', '2004-07-13 19:08:20.000000', NULL, 1),
(809606, 90394, 3087, '<td valign="top">Nicely done and well chosen location with nice plain background. Great pan! 7</td>', 'Nicely done and well chosen location with nice plain background. Great pan! 7', '2004-07-13 19:09:25.000000', NULL, 1),
(809653, 90516, 16821, '<td valign="top">Very nice texture, artistic results.</td>', 'Very nice texture, artistic results.', '2004-07-13 19:38:58.000000', NULL, 1),
