(809742, 90108, 18403, '<td valign="top">Too smaaaaalll.   You are permitted up to 640 pixels per axis.  The calves would show up much better if a larger scale is used.</td>', 'Too smaaaaalll.   You are permitted up to 640 pixels per axis.  The calves would show up much better if a larger scale is used.', '2004-07-13 20:52:46.000000', NULL, 1),
(809752, 90384, 13602, '<td valign="top">Whoah filany an image without the word "freedom" in the title. I can''t really feel the freedom in your image but atleast you had the decency to not try to stretch it with the title. You get an extra point for that. The image is a cute snaphot, but it looks like the focus is more on the stuff in the front and the children are a bit out of focus. I would of liked it more the other way around. Good luck!</td>', 'Whoah filany an image without the word "freedom" in the title. I can''t really feel the freedom in your image but atleast you had the decency to not try to stretch it with the title. You get an extra point for that. The image is a cute snaphot, but it looks like the focus is more on the stuff in the front and the children are a bit out of focus. I would of liked it more the other way around. Good luck!', '2004-07-13 20:58:48.000000', NULL, 1),
(809754, 90562, 16230, '<td valign="top">A very creative idea, well executed.</td>', 'A very creative idea, well executed.', '2004-07-13 20:59:41.000000', NULL, 1),
