(811220, 90111, 16106, '<td valign="top">Lovely desat shot but if I were to list all the word that came into my head to describe this shot I think I would get half way through the dictionary before I got to the word freedom. IMHO you missed the challenge but got a shot that would ribbon in many other challenges.</td>', 'Lovely desat shot but if I were to list all the word that came into my head to describe this shot I think I would get half way through the dictionary before I got to the word freedom. IMHO you missed the challenge but got a shot that would ribbon in many other challenges.', '2004-07-14 14:32:16.000000', NULL, 1),
(811250, 90483, 16106, '<td valign="top">I like th iconograph here, and also the framing, but the blue balon against the blue sky lacks visual pop. The edges look soft and the ribbon fades in and out of visibility. Very close to being a top pick.</td>', 'I like th iconograph here, and also the framing, but the blue balon against the blue sky lacks visual pop. The edges look soft and the ribbon fades in and out of visibility. Very close to being a top pick.', '2004-07-14 14:42:39.000000', NULL, 1),
(811270, 90352, 16106, '<td valign="top">This shot looked like the winner in thumbnail, but it is too softly focused in the lower half, and that odd vein in the wall  (which is in perfect focus ) keeps drawing my eye away from the subject. Almost there.</td>', 'This shot looked like the winner in thumbnail, but it is too softly focused in the lower half, and that odd vein in the wall  (which is in perfect focus ) keeps drawing my eye away from the subject. Almost there.', '2004-07-14 14:47:21.000000', NULL, 1),
