(814569, 90376, 12611, '<td valign="top">if you put yourself in all the pictures people know who you are. I like the one in th emiddle of the road in the snowstorm or the candid self protrait from 2 weeks ago better.</td>', 'if you put yourself in all the pictures people know who you are. I like the one in th emiddle of the road in the snowstorm or the candid self protrait from 2 weeks ago better.', '2004-07-16 22:43:52.000000', NULL, 1),
(814571, 90580, 12611, '<td valign="top">I love the way you made thewhite walls silvery-gray. Teo things distract from an overall fantastic picture. the clock face paper bubling up, and the glare on the right.</td>', 'I love the way you made thewhite walls silvery-gray. Teo things distract from an overall fantastic picture. the clock face paper bubling up, and the glare on the right.', '2004-07-16 22:49:59.000000', NULL, 1),
(814573, 90207, 16821, '<td valign="top">Is she taking her ring off too? I wish she was in focus. Nice composition, and it is a sad commentary on marriage in America.</td>', 'Is she taking her ring off too? I wish she was in focus. Nice composition, and it is a sad commentary on marriage in America.', '2004-07-16 22:51:06.000000', NULL, 1),
(814575, 90205, 12611, '<td valign="top">I am afraid to look around front and see frank and beans- this is erotic in a tabboo sort of way. very well done though. I can''t wait to read  all about this picture.</td>', 'I am afraid to look around front and see frank and beans- this is erotic in a tabboo sort of way. very well done though. I can''t wait to read  all about this picture.', '2004-07-16 22:52:27.000000', NULL, 1),
